package net.civeira.phylax.feature.access.role.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.resourceserver.domain.ResourceServerReference;

class ResourceServerVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property resource server of role ")
  void test_resource_server_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10",
        ResourceServerVO.fromReference("10").getResourceServerUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertEquals("11",
        ResourceServerVO.tryFromReference("11").getResourceServerUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertEquals("12",
        ResourceServerVO.tryFromReference("12", fails).getResourceServerUid().orElse(null),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertFalse(ResourceServerVO.nullValue().getResourceServer().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ResourceServerVO.tryFrom(null).getResourceServer().isPresent(),
        "With a null value, no present result");
    Assertions.assertFalse(ResourceServerVO.fromReference(null).getResourceServer().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(ResourceServerReference.of("one"),
        ResourceServerVO.from(ResourceServerReference.of("one")).getResourceServer().orElse(null));
    Assertions.assertThrows(ConstraintException.class,
        () -> ResourceServerVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + ResourceServerReference.of("one") + "]",
        ResourceServerVO.from(ResourceServerReference.of("one")).toString());
  }
}
